sys_script_include.script:
var FormSubmission = Class.create();
FormSubmission.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    submitFormData: function() {
        var sys_id = this.getParameter('sysparm_sys_id'); 
        var text_field = this.getParameter('sysparm_text_field');
        var dropdown_field = this.getParameter('sysparm_dropdown_field');
        var checkbox_field = this.getParameter('sysparm_checkbox_field') === 'true'; // Convert to boolean
        var radio_field = this.getParameter('sysparm_radio_field');

        var gr = new GlideRecord('u_custom_form_data'); 

        if (sys_id && gr.get(sys_id)) {
            // Update existing record
            gr.u_text_field = text_field;
            gr.u_dropdown_field = dropdown_field;
            gr.u_checkbox_field = checkbox_field;
            gr.u_radio_field = radio_field;
            gr.update();
            return "Data updated successfully!";
        } else {
            // Create new record
            gr.initialize();
            gr.u_text_field = text_field;
            gr.u_dropdown_field = dropdown_field;
            gr.u_checkbox_field = checkbox_field;
            gr.u_radio_field = radio_field;
            gr.insert();

            return "New user registered successfully!";
        }
    },

    getUserData: function() {
        var sys_id = this.getParameter('sysparm_sys_id'); 
        var gr = new GlideRecord('u_custom_form_data');

        if (gr.get(sys_id)) {
            var userData = {
                text_field: gr.u_text_field,
                dropdown_field: gr.u_dropdown_field,
                checkbox_field: gr.u_checkbox_field.toString(), // Convert to string
                radio_field: gr.u_radio_field
            };
            return JSON.stringify(userData);
        }
        return JSON.stringify(null);
    }
});
